  \node[o] (l1) at (-3.00,-3.90) {$OA$ là đường trung trực của $BC$};
  \draw[m] (l1) -- (l0);
  \node[gt] (l2) at (-3.00,-4.95) {$AB = AC$; $OB = OC$};
  \draw[m] (l2) -- (l1);
  \draw[m] (l0.north) |- (s1.west);
  \node[gt] (r0) at (3.00,-2.70) {$\widehat{AOB}$ chung};
  \draw[m] (r0.north) |- (s1.east);
\end{tikzpicture}

